extension.install:
if (!$forum_db->table_exists('punbb_fixture_markers'))
{
	$schema = array(
		'FIELDS'		=> array(
			'id'			=> array(
				'datatype'		=> 'SERIAL',
				'allow_null'	=> false
			),
			'request_id'	=> array(
				'datatype'		=> 'VARCHAR(40)',
				'allow_null'	=> false,
				'default'		=> '\'\''
			),
			'extension_id'	=> array(
				'datatype'		=> 'VARCHAR(150)',
				'allow_null'	=> false,
				'default'		=> '\'\''
			),
			'hook_id'		=> array(
				'datatype'		=> 'VARCHAR(150)',
				'allow_null'	=> false,
				'default'		=> '\'\''
			),
			'seen'			=> array(
				'datatype'		=> 'TEXT',
				'allow_null'	=> true
			)
		),
		'PRIMARY KEY'	=> array('id'),
		'INDEXES'		=> array(
			'request_id_idx'	=> array('request_id')
		)
	);

	$forum_db->create_table('punbb_fixture_markers', $schema);
}

if (!$forum_db->field_exists('forums', 'punbb_fixture_hidden'))
	$forum_db->add_field('forums', 'punbb_fixture_hidden', 'TINYINT(1)', false, 0);

forum_config_add('o_punbb_fixture_banner', 'punbb_fixture');

hooks.hook:
if (!defined('PUNBB_FIXTURE_FUNCTIONS_LOADED'))
	require $ext_info['path'].'/functions.php';

$query['WHERE'] = '('.$query['WHERE'].') AND f.punbb_fixture_hidden=0';

punbb_fixture_mark($ext_info['id'], 'in_qr_get_cats_and_forums', array('where' => $query['WHERE']));

if (!defined('PUNBB_FIXTURE_FUNCTIONS_LOADED'))
	require $ext_info['path'].'/functions.php';

if (isset($_SERVER['HTTP_X_PUNBB_FIXTURE_ADDRESS']) && filter_var($_SERVER['HTTP_X_PUNBB_FIXTURE_ADDRESS'], FILTER_VALIDATE_IP) !== false)
{
	punbb_fixture_mark($ext_info['id'], 'fn_get_remote_address_start', array('returned' => $_SERVER['HTTP_X_PUNBB_FIXTURE_ADDRESS']));

	return $_SERVER['HTTP_X_PUNBB_FIXTURE_ADDRESS'];
}

if (!defined('PUNBB_FIXTURE_FUNCTIONS_LOADED'))
	require $ext_info['path'].'/functions.php';

punbb_fixture_mark($ext_info['id'], 'vt_row_new_post_entry_data', array(
	'post_id'	=> $cur_post['id'],
	'ob_level'	=> ob_get_level()
));

echo "\t\t\t\t\t".'<p class="punbb-fixture-echo" data-post-id="'.intval($cur_post['id']).'">punbb_fixture</p>'."\n";

if (!defined('PUNBB_FIXTURE_FUNCTIONS_LOADED'))
	require $ext_info['path'].'/functions.php';

$punbb_fixture_banner = punbb_fixture_banner();

punbb_fixture_mark($ext_info['id'], 'in_main_output_start', $punbb_fixture_banner + array('url' => $ext_info['url']));

echo "\t".'<p id="punbb-fixture-banner">'.forum_htmlencode(implode(' ', $punbb_fixture_banner['parts'])).'</p>'."\n";
